import './index.css';
import { useState } from 'react';
import { usePortfolio } from './hooks/usePortfolio';
import StockCard from './components/StockCard';
import AlertPanel from './components/AlertPanel';
import PortfolioChart from './components/PortfolioChart';

const TICKER_COLORS = { HLT: '#34D399', WLT: '#FBBF24', SOC: '#60A5FA' };

function getGreeting() {
  const h = new Date().getHours();
  if (h < 12) return 'Good morning';
  if (h < 17) return 'Good afternoon';
  return 'Good evening';
}

export default function App() {
  const { portfolio, loading, error, lastUpdated, logActivity, syncGroww } = usePortfolio();
  const [syncMsg, setSyncMsg] = useState(null);

  const handleSync = async () => {
    setSyncMsg('Syncing Groww…');
    const res = await syncGroww();
    if (res?.wlt) {
      setSyncMsg(`Wealth synced → ${Math.round(res.wlt.new_price).toLocaleString()} VTL`);
      setTimeout(() => setSyncMsg(null), 4000);
    }
  };

  if (loading && !portfolio) return (
    <div style={{ minHeight:'100vh', display:'flex', alignItems:'center', justifyContent:'center', flexDirection:'column', gap:16 }}>
      <div style={{ fontFamily:'var(--font-display)', fontSize:32, fontWeight:800, background:'linear-gradient(135deg, #FBBF24, #EEF0F6)', WebkitBackgroundClip:'text', WebkitTextFillColor:'transparent', letterSpacing:'-0.03em' }}>VitalityX</div>
      <div style={{ fontSize:13, color:'var(--text-muted)', fontFamily:'var(--font-body)' }}>Loading your life portfolio…</div>
    </div>
  );

  if (error) return (
    <div style={{ minHeight:'100vh', display:'flex', alignItems:'center', justifyContent:'center', padding:24 }}>
      <div style={{ background:'#141826', border:'1px solid rgba(248,113,113,0.3)', borderRadius:20, padding:32, maxWidth:400, textAlign:'center' }}>
        <div style={{ fontSize:32, marginBottom:12 }}>⚡</div>
        <div style={{ fontFamily:'var(--font-display)', fontWeight:700, marginBottom:8, color:'#F87171', fontSize:18 }}>API Offline</div>
        <div style={{ fontSize:13, color:'var(--text-secondary)', lineHeight:1.6 }}>{error}</div>
        <div style={{ marginTop:12, fontFamily:'var(--font-mono)', fontSize:11, color:'var(--text-muted)', background:'rgba(255,255,255,0.04)', padding:'8px 14px', borderRadius:8 }}>
          uvicorn main:app --reload
        </div>
      </div>
    </div>
  );

  const stocks   = portfolio?.stocks || [];
  const alerts   = portfolio?.alerts || [];
  const totalVTL = portfolio?.total_vtl || 0;
  const tickerData = stocks.map(s => ({ ...s, color: TICKER_COLORS[s.ticker] }));

  return (
    <div style={{ minHeight:'100vh', maxWidth:1140, margin:'0 auto', padding:'0 24px 80px' }}>

      {/* ── Ticker strip ── */}
      <div style={{ borderBottom:'1px solid rgba(255,255,255,0.06)', overflow:'hidden', height:38, display:'flex', alignItems:'center' }}>
        <div style={{ display:'flex', gap:44, alignItems:'center', animation:'ticker 20s linear infinite', whiteSpace:'nowrap' }}>
          {[...tickerData, ...tickerData].map((t, i) => (
            <span key={i} style={{ fontFamily:'var(--font-mono)', fontSize:11, display:'flex', gap:8, alignItems:'center' }}>
              <span style={{ color:'var(--text-muted)', letterSpacing:'0.06em' }}>{t.name?.toUpperCase()}</span>
              <span style={{ color: t.color }}>{Math.round(t.price).toLocaleString()} VTL</span>
              <span style={{ color: t.direction==='up'?'#34D399': t.direction==='down'?'#F87171':'var(--text-muted)', opacity:0.8 }}>
                {t.direction==='up'?'▲':t.direction==='down'?'▼':'—'}{Math.abs(t.change_pct).toFixed(1)}%
              </span>
            </span>
          ))}
        </div>
      </div>

      {/* ── Header ── */}
      <div style={{ padding:'36px 0 28px', animation:'fadeUp 0.4s ease both' }}>
        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', flexWrap:'wrap', gap:16 }}>
          <div>
            <div style={{ fontSize:13, color:'var(--text-muted)', marginBottom:6, fontFamily:'var(--font-body)' }}>
              {getGreeting()}, Shrithik 👋
            </div>
            <div style={{ fontFamily:'var(--font-display)', fontWeight:800, fontSize:36, background:'linear-gradient(135deg, #FBBF24 0%, #EEF0F6 55%)', WebkitBackgroundClip:'text', WebkitTextFillColor:'transparent', letterSpacing:'-0.03em', lineHeight:1 }}>
              VitalityX
            </div>
            <div style={{ fontSize:12, color:'var(--text-muted)', marginTop:6, fontFamily:'var(--font-body)' }}>
              {new Date().toLocaleDateString('en-IN', { weekday:'long', day:'numeric', month:'long' })}
            </div>
          </div>

          <div style={{ background:'linear-gradient(145deg, #141826, #1C2133)', border:'1px solid rgba(251,191,36,0.2)', borderRadius:18, padding:'18px 24px', textAlign:'right', minWidth:180 }}>
            <div style={{ fontSize:11, color:'var(--text-muted)', marginBottom:6, letterSpacing:'0.06em', textTransform:'uppercase', fontFamily:'var(--font-body)' }}>
              Total portfolio
            </div>
            <div style={{ fontFamily:'var(--font-mono)', fontSize:32, fontWeight:500, color:'#FBBF24', letterSpacing:'-0.02em', lineHeight:1 }}>
              {Math.round(totalVTL).toLocaleString()}
              <span style={{ fontSize:13, color:'var(--text-muted)', marginLeft:5 }}>VTL</span>
            </div>
            <div style={{ fontSize:11, color:'var(--text-muted)', marginTop:5, fontFamily:'var(--font-body)' }}>
              Vitals · {stocks.length} stocks active
            </div>
          </div>
        </div>
      </div>

      {/* ── Sync banner ── */}
      {syncMsg && (
        <div style={{ background:'rgba(251,191,36,0.08)', border:'1px solid rgba(251,191,36,0.2)', borderRadius:10, padding:'10px 16px', marginBottom:20, fontFamily:'var(--font-body)', fontSize:13, color:'#FBBF24', animation:'fadeUp 0.2s ease both', display:'flex', alignItems:'center', gap:8 }}>
          <span>◈</span> {syncMsg}
        </div>
      )}

      {/* ── Stock cards ── */}
      <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fit, minmax(300px, 1fr))', gap:16, marginBottom:24 }}>
        {stocks.map((s, i) => (
          <StockCard key={s.ticker} stock={{ ...s, peak_price: s.price * 1.1 }} onLog={t => logActivity(t)} onSync={handleSync} animDelay={i * 0.08}/>
        ))}
      </div>

      <PortfolioChart/>

      {/* ── Alerts ── */}
      <AlertPanel alerts={alerts}/>

      {/* ── Footer ── */}
      <div style={{ marginTop:40, paddingTop:20, borderTop:'1px solid rgba(255,255,255,0.05)', display:'flex', justifyContent:'space-between', alignItems:'center' }}>
        <div style={{ fontSize:11, color:'var(--text-muted)', letterSpacing:'0.04em' }}>VITALITYX · CURRENCY: VITALS (VTL)</div>
        <div style={{ fontSize:11, color:'var(--text-muted)' }}>
          {lastUpdated ? `Updated ${lastUpdated.toLocaleTimeString('en-IN', { hour:'2-digit', minute:'2-digit' })}` : 'Live'}
        </div>
      </div>

    </div>
  );
}
